 // Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
  JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d.]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

/**
 * ASSISTENTE DE INVESTIMENTOS - DIO
 * Cruza clientes com investimentos e
 * gera mensagens personalizadas.
 */

// ======================================
// 1. RECEBER DADOS DO MERGE
// ======================================

const entradas = $input.all().map(item => item.json);

let clientes = [];
let investimentos = [];

for (const entrada of entradas) {
  const dados = entrada.body ?? entrada;

  if (Array.isArray(dados.clientes)) {
    clientes = dados.clientes;
  }

  if (Array.isArray(entrada.investimentos)) {
    investimentos = entrada.investimentos;
  }

  if (Array.isArray(dados.investimentos)) {
    investimentos = dados.investimentos;
  }
}

// ======================================
// 2. FUNÇÕES AUXILIARES
// ======================================

// Converte valores como R$ 12.500,00
function paraNumero(valor) {
  if (typeof valor === "number") {
    return valor;
  }

  const texto = String(valor ?? "")
    .replace(/[^\d,.-]/g, "");

  const normalizado = texto.includes(",")
    ? texto.replace(/\./g, "").replace(",", ".")
    : texto;

  return Number(normalizado) || 0;
}

// Formata valores em reais
function brl(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// Escolhe uma mensagem aleatória
function pick(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// ======================================
// 3. VALIDAR DADOS
// ======================================

if (!clientes.length) {
  throw new Error("Nenhum cliente encontrado no Merge.");
}

if (!investimentos.length) {
  throw new Error("Nenhum investimento encontrado no Merge.");
}

// ======================================
// 4. PROCESSAR CLIENTES
// ======================================

const resultados = clientes.map(c => {

  const nome = c.nome ?? "Cliente";
  const email = c.email ?? "";
  const perfil = String(c.perfil ?? "").trim();

  const saldoNum = paraNumero(c.saldo);
  const saldoTexto = brl(saldoNum);

  // Busca investimentos do mesmo perfil
  const opcoesPerfil = investimentos.filter(i =>
    String(i.perfil ?? "").trim().toLowerCase() ===
    perfil.toLowerCase()
  );

  // Busca opções compatíveis com o saldo
  const opcoesValidas = opcoesPerfil
    .filter(i => saldoNum >= paraNumero(i.minimo))
    .sort((a, b) =>
      paraNumero(b.minimo) - paraNumero(a.minimo)
    );

  // Prioriza a opção de maior mínimo
  // que o saldo consegue atender
  let escolhido = opcoesValidas[0];

  // Se não puder investir, usa a opção
  // de menor valor para orientar
  if (!escolhido && opcoesPerfil.length) {
    escolhido = [...opcoesPerfil].sort((a, b) =>
      paraNumero(a.minimo) - paraNumero(b.minimo)
    )[0];
  }

  let motivo = "";
  let mensagens = [];

  // ====================================
  // 5. GERAR MENSAGENS PERSONALIZADAS
  // ====================================

  if (!escolhido) {

    motivo = "sem_opcao";

    mensagens = [
      `Olá ${nome}! Ainda não encontramos investimentos compatíveis com seu perfil ${perfil}.`,

      `Oi ${nome}! No momento, não temos uma opção cadastrada para o perfil ${perfil}.`,

      `${nome}, vamos analisar novas alternativas para seu perfil de investidor ${perfil}.`
    ];

  } else {

    const minimo = paraNumero(escolhido.minimo);
    const minimoTexto = brl(minimo);
    const produto = escolhido.produto;
    const rentabilidade = escolhido.rentabilidade;

    if (saldoNum >= minimo) {

      motivo = "saldo_ok";

      mensagens = [

        `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${produto}** (mínimo ${minimoTexto}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${rentabilidade}.`,

        `Oi ${nome}! Recomendação para perfil ${perfil}: **${produto}** (mínimo ${minimoTexto}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${rentabilidade}.`,

        `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${produto}** (mínimo ${minimoTexto}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${rentabilidade}.`

      ];

    } else {

      motivo = "saldo_insuficiente";

      const faltante = minimo - saldoNum;

      mensagens = [

        `Olá ${nome}! Para seu perfil ${perfil}, encontramos **${produto}**, que exige investimento mínimo de ${minimoTexto}. Atualmente você possui ${saldoTexto}, faltando ${brl(faltante)} para atingir o mínimo.`,

        `Oi ${nome}! Uma alternativa para o perfil ${perfil} é **${produto}**. O investimento mínimo é ${minimoTexto}. Você precisaria adicionar ${brl(faltante)} ao seu saldo atual.`,

        `${nome}, considerando seu perfil ${perfil}, o produto **${produto}** pode ser uma alternativa. Seu saldo atual é ${saldoTexto} e o mínimo necessário é ${minimoTexto}.`

      ];
    }
  }

  // ====================================
  // 6. RETORNAR RESULTADO DO CLIENTE
  // ====================================

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido ?? null,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };

});

// ======================================
// 7. RETORNO FINAL PARA O N8N
// ======================================

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];
